#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

struct Model { uint32_t labels, channels, dims, sparsity; uint64_t seed; std::vector<uint8_t> nvals; std::vector<float> weights,bias; std::vector<int8_t> proto; std::vector<std::string> names; };
static uint64_t smix(uint64_t z){ z+=0x9E3779B97F4A7C15ULL; z=(z^(z>>30))*0xBF58476D1CE4E5B9ULL; z=(z^(z>>27))*0x94D049BB133111EBULL; return z^(z>>31); }
static uint64_t hash_code(const std::vector<uint32_t>& c,size_t start,size_t n,uint64_t salt){ uint64_t h=0xCBF29CE484222325ULL^salt; for(size_t i=0;i<n;i++){h*=0x100000001B3ULL; h+=uint64_t(c[start+i])+1;} return smix(h); }
static std::vector<uint32_t> utf8(const std::string& s,bool fold){ std::vector<uint32_t> out{0x110000}; bool space=true; size_t i=0; while(i<s.size()){ unsigned char b=s[i]; uint32_t cp=0; size_t k=1; if(b<0x80) cp=b; else if((b&0xE0)==0xC0&&i+1<s.size()){cp=((b&31)<<6)|(s[i+1]&63);k=2;} else if((b&0xF0)==0xE0&&i+2<s.size()){cp=((b&15)<<12)|((s[i+1]&63)<<6)|(s[i+2]&63);k=3;} else if((b&0xF8)==0xF0&&i+3<s.size()){cp=((b&7)<<18)|((s[i+1]&63)<<12)|((s[i+2]&63)<<6)|(s[i+3]&63);k=4;} else {i++;continue;} i+=k; if(cp==9||cp==10||cp==13||cp==32){if(!space){out.push_back(0x110003);space=true;} continue;} if(cp<32||cp==0x7f) continue; if(space){out.push_back(0x110002);space=false;} if(fold&&cp>=65&&cp<=90) cp+=32; out.push_back(cp);} if(!space) out.push_back(0x110003); out.push_back(0x110001); return out; }
static std::vector<int8_t> encode(const Model&m,const std::string& text){ std::vector<std::vector<uint64_t>> all; int maxn=*std::max_element(m.nvals.begin(),m.nvals.end()); for(int view=0;view<2;view++){auto cps=utf8(text,view==1); for(int n=1;n<=maxn;n++){std::vector<uint64_t> h; if(cps.size()>=size_t(n)){for(size_t st=0;st+n<=cps.size();st++){uint64_t salt=((view+1)*0x9E3779B185EBCA87ULL)^(uint64_t(n)*0xC2B2AE3D27D4EB4FULL); h.push_back(hash_code(cps,st,n,salt));}} all.push_back(std::move(h));}}
 std::vector<int8_t> out(size_t(m.channels)*m.dims); for(int view=0;view<2;view++) for(size_t ni=0;ni<m.nvals.size();ni++){int n=m.nvals[ni]; const auto& hs=all[view*maxn+n-1]; std::unordered_map<uint64_t,int> counts; for(auto h:hs) counts[h]++; std::vector<float> v(m.dims); for(auto [key,count]:counts){float w=1.f+std::log(float(count)); uint64_t base=key^(m.seed+uint64_t(view*m.nvals.size()+ni)*0x9E3779B1ULL); for(uint32_t j=0;j<m.sparsity;j++){uint64_t code=smix(base+uint64_t(j)*0xD6E8FEB86659FD93ULL); size_t idx=code&(m.dims-1); v[idx]+=w*((code>>63)?-1.f:1.f);}} float norm=0; for(float x:v) norm+=x*x; norm=std::sqrt(norm); for(uint32_t d=0;d<m.dims;d++){float q=norm?std::round(std::max(-127.f,std::min(127.f,v[d]/norm*127.f))):0; out[(view*m.nvals.size()+ni)*m.dims+d]=int8_t(q);}}
 return out; }
static Model load(const std::string& path){ Model m; std::ifstream f(path,std::ios::binary); char magic[6]; f.read(magic,6); uint32_t nv; f.read(reinterpret_cast<char*>(&m.labels),4); f.read(reinterpret_cast<char*>(&m.channels),4); f.read(reinterpret_cast<char*>(&m.dims),4); f.read(reinterpret_cast<char*>(&m.sparsity),4); f.read(reinterpret_cast<char*>(&m.seed),8); f.read(reinterpret_cast<char*>(&nv),4); m.nvals.resize(nv); f.read(reinterpret_cast<char*>(m.nvals.data()),nv); m.weights.resize(m.channels); m.bias.resize(m.labels); m.proto.resize(size_t(m.channels)*m.labels*m.dims); f.read(reinterpret_cast<char*>(m.weights.data()),m.weights.size()*4); f.read(reinterpret_cast<char*>(m.bias.data()),m.bias.size()*4); f.read(reinterpret_cast<char*>(m.proto.data()),m.proto.size()); m.names.resize(m.labels); for(uint32_t i=0;i<m.labels;i++){uint16_t len; f.read(reinterpret_cast<char*>(&len),2); f.seekg(len,std::ios::cur); f.read(reinterpret_cast<char*>(&len),2); m.names[i].resize(len); f.read(m.names[i].data(),len);} return m; }
static int predict(const Model&m,const std::string& text){ auto v=encode(m,text); std::vector<float> raw(size_t(m.channels)*m.labels); for(uint32_t c=0;c<m.channels;c++) for(uint32_t k=0;k<m.labels;k++){int32_t sum=0; const int8_t* p=&m.proto[(size_t(c)*m.labels+k)*m.dims]; const int8_t* q=&v[size_t(c)*m.dims]; for(uint32_t d=0;d<m.dims;d++) sum+=int32_t(p[d])*int32_t(q[d]); raw[size_t(c)*m.labels+k]=float(sum)/(127.f*127.f);} std::vector<float> scores(m.labels); for(uint32_t k=0;k<m.labels;k++){float score=m.bias[k]; for(uint32_t c=0;c<m.channels;c++){float mean=0,ss=0; for(uint32_t j=0;j<m.labels;j++) mean+=raw[size_t(c)*m.labels+j]; mean/=m.labels; for(uint32_t j=0;j<m.labels;j++){float z=raw[size_t(c)*m.labels+j]-mean; ss+=z*z;} float sd=std::sqrt(ss/m.labels); score+=m.weights[c]*((raw[size_t(c)*m.labels+k]-mean)/std::max(sd,1e-6f));} scores[k]=score;} return int(std::max_element(scores.begin(),scores.end())-scores.begin()); }
int main(int argc,char**argv){if(argc<3){std::cerr<<"usage: fastlingo_native model.bin text [iterations]\n";return 2;} Model m=load(argv[1]); std::string text=argv[2]; int it=argc>3?std::stoi(argv[3]):1; int pred=predict(m,text); if(it==1){std::cout<<pred<<"\n";return 0;} auto start=std::chrono::steady_clock::now(); for(int i=0;i<it;i++) pred=predict(m,text); double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()/it; std::cout<<"label_index="<<pred<<" avg_ms="<<ms<<"\n"; }

